PARAMS = ['R0','kout','Imax','IC50']
def predict(df, p):
    def solve_one(dose, times):
        times = np.asarray(times, float)
        def rhs(t, y):
            C = pk_conc(dose, t)
            kin = p['R0']*p['kout']
            return [kin - p['kout']*(1 - p['Imax']*C/(p['IC50']+C))*y[0]]
        sol = solve_ivp(rhs, (0, times.max()), [p['R0']], t_eval=times, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

